    uinstr_is g (mword_of_int 0xf6) true
      (C_ADDI (mword_of_int 48 : mword 6, Regidx (mword_of_int 2))).
  Proof.
    iIntros "#Ht".
    uis_rvc2 g 0xf6 (mword_of_int 0x1141 : mword 16) udec_1141.
  Qed.

