  (* =================================================================== *)
  (* §3 Where the catalog comes from.                                      *)
  (* =================================================================== *)

  (* [cat_code] is defined above, at the top of the section, because every
     per-pc lemma consumes it. This is its INTRODUCTION, and the ONE place in
     the whole development where the program's bytes meet the process image:
     the entry hands out [utext_all gt M pm] -- the text half of the heap,
     over the image the kernel actually loaded -- and the two section
     hypotheses say that image contains the dump ([cat_text_sub]) and that
     the executable segment is X-and-not-W ([Hx]), which is what puts those
     bytes in the TEXT half rather than the data one. Both are discharged
     HERE, once, instead of in each of the 388 per-pc lemmas. *)

  (* AND THE READ-ONLY IMAGE BESIDE IT. A program's string LITERALS are not
     in [CatInstrs.cat_bytes] and they are not in the data half either:
     .rodata shares the EXECUTABLE segment's pages, so its bytes are
     X-and-not-W and the heap files them under [γt] exactly as it files the
     code. init's four format strings sit at 0x970..0x9e7, inside the R-X
     segment, and vprintf LOADS them one byte at a time. This is the part of
     [CatData.cat_data] that lands there -- everything below the end of the
     executable segment -- and [UserHeap.utext_str_of_img] cuts a literal out
     of it at a concrete base and length. *)
  Definition cat_ro : gmap Z (bv 8) :=
    filter (fun kv => (kv.1 < 4096)%Z) CatData.cat_data.

  Definition cat_rodata (g : gname) : iProp Σ := utext_img g cat_ro.

  Global Instance cat_rodata_persistent g : Persistent (cat_rodata g).
  Proof. apply _. Qed.

  Global Typeclasses Opaque cat_rodata.

  Lemma cat_rodata_of_text : utext_all gt M pm -∗ cat_rodata gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               cat_ro !! a = Some b -> M !! a = Some b).
    { intros a b Hb. apply map_lookup_filter_Some in Hb as [Hb _].
      exact (Hsub2 a b Hb). }
    assert (Hp : forall a : Z, is_Some (cat_ro !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply map_lookup_filter_Some in Hb as [Hb Hlt].
      apply Hx.
      pose proof (cat_data_key_nonneg a b Hb) as Hge.
      simpl in Hlt. lia. }
    iIntros "#Ht". rewrite /cat_rodata.
    iApply (utext_img_of_all gt M pm cat_ro Hin Hp with "Ht").
  Qed.

  Lemma cat_code_of_text : utext_all gt M pm -∗ cat_code gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               CatInstrs.cat_bytes !! a = Some b -> M !! a = Some b)
      by exact Hsub.
    assert (Hp : forall a : Z, is_Some (CatInstrs.cat_bytes !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply Hx.
      pose proof (cat_bytes_key_lt a b Hb) as Hlt.
      pose proof (cat_bytes_key_nonneg a b Hb) as Hge. lia. }
    iIntros "#Ht". rewrite /cat_code.
    iApply (utext_img_of_all gt M pm CatInstrs.cat_bytes Hin Hp with "Ht").
  Qed.

End UCodeCat.
